/// How a modal element is presented.
enum DtxModalKind { dialog, drawer, sheet }

/// `dialog`/`drawer`/`sheet { ... }`: shown as a modal route while the
/// element is in the view -- focus is trapped inside it and restored when it
/// closes. Dismissing it closes it; it opens again when the view shows the
/// element again.
class DtxModal extends StatefulWidget {
  const DtxModal({super.key, required this.kind, this.title, this.style, required this.children});

  final DtxModalKind kind;
  final String? title;
  final DtxStyle? style;
  final List<Widget> children;

  @override
  State<DtxModal> createState() => _DtxModalState();
}

class _DtxModalState extends State<DtxModal> {
  late final ValueNotifier<DtxModal> _shown = ValueNotifier<DtxModal>(widget);
  Route<void>? _route;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _open());
  }

  @override
  void didUpdateWidget(DtxModal oldWidget) {
    super.didUpdateWidget(oldWidget);
    _shown.value = widget;
  }

  void _open() {
    if (!mounted) {
      return;
    }
    final navigator = Navigator.of(context, rootNavigator: true);
    final themes = InheritedTheme.capture(from: context, to: navigator.context);
    final label = MaterialLocalizations.of(context).modalBarrierDismissLabel;
    final route = switch (widget.kind) {
      DtxModalKind.dialog => DialogRoute<void>(
        context: context,
        themes: themes,
        barrierLabel: label,
        builder: (context) => Dialog(child: _content(context)),
      ),
      DtxModalKind.sheet => ModalBottomSheetRoute<void>(
        capturedThemes: themes,
        barrierLabel: label,
        isScrollControlled: true,
        builder: (context) => SafeArea(child: _content(context)),
      ),
      DtxModalKind.drawer => RawDialogRoute<void>(
        barrierDismissible: true,
        barrierLabel: label,
        barrierColor: Theme.of(context).colorScheme.scrim.withValues(alpha: 0.32),
        pageBuilder: (context, animation, secondaryAnimation) => themes.wrap(
          Align(
            alignment: AlignmentDirectional.centerStart,
            child: Drawer(child: SafeArea(child: _content(context))),
          ),
        ),
        transitionBuilder: (context, animation, secondaryAnimation, child) => SlideTransition(
          position: Tween<Offset>(begin: const Offset(-1, 0), end: Offset.zero).animate(animation),
          child: child,
        ),
      ),
    };
    _route = route;
    unawaited(navigator.push(route).whenComplete(() => _route = null));
  }

  Widget _content(BuildContext context) {
    return ValueListenableBuilder<DtxModal>(
      valueListenable: _shown,
      builder: (context, modal, _) {
        final title = modal.title;
        return Semantics(
          scopesRoute: true,
          namesRoute: title != null,
          label: title,
          explicitChildNodes: true,
          child: SingleChildScrollView(
            padding: EdgeInsets.all(DtxTokens.of(context).inset),
            child: DtxStack(style: modal.style, children: [if (title != null) _Title(title, Theme.of(context).textTheme.titleLarge), ...modal.children]),
          ),
        );
      },
    );
  }

  @override
  void dispose() {
    final route = _route;
    if (route != null && route.isActive) {
      route.navigator?.removeRoute(route);
    }
    _shown.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}

