/// The colours of [tone], or the theme's neutral container colours.
DtxTone _toneColors(BuildContext context, String? tone) {
  if (tone != null) {
    return DtxTokens.of(context).tone(tone);
  }
  final scheme = Theme.of(context).colorScheme;
  return DtxTone(background: scheme.secondaryContainer, foreground: scheme.onSecondaryContainer);
}

