      mainAxisSize: MainAxisSize.min,
      spacing: DtxTokens.of(context).gap,
      children: [
        ExcludeSemantics(child: avatar),
        Text(label, style: Theme.of(context).textTheme.titleMedium),
      ],
    );
    return dtxStyled(context, style, brand);
  }
}

