/// A button's presentation (`kind(...)`).
enum DtxButtonKind { standard, primary, secondary, link }

/// `button(label) : onClick(...), kind(k)?, tone(t)?`: a button; without a
/// handler it is shown disabled.
class DtxButton extends StatelessWidget {
  const DtxButton({super.key, required this.label, this.kind = DtxButtonKind.standard, this.tone, this.onPressed, this.style});

  final String label;
  final DtxButtonKind kind;
  final String? tone;
  final VoidCallback? onPressed;
  final DtxStyle? style;

  @override
  Widget build(BuildContext context) {
    final toneName = tone;
    final colors = toneName == null ? null : DtxTokens.of(context).tone(toneName);
    final buttonStyle = colors == null ? null : ButtonStyle(backgroundColor: WidgetStatePropertyAll(colors.background), foregroundColor: WidgetStatePropertyAll(colors.foreground));
    final child = Text(label);
    final button = switch (kind) {
      DtxButtonKind.primary => FilledButton(onPressed: onPressed, style: buttonStyle, child: child),
      DtxButtonKind.standard => FilledButton.tonal(onPressed: onPressed, style: buttonStyle, child: child),
      DtxButtonKind.secondary => OutlinedButton(onPressed: onPressed, style: buttonStyle, child: child),
      DtxButtonKind.link => TextButton(onPressed: onPressed, style: buttonStyle, child: child),
    };
    return dtxStyled(context, style, button);
  }
}

