      DtxButtonKind.primary => FilledButton(onPressed: onPressed, child: child),
      DtxButtonKind.standard => FilledButton.tonal(onPressed: onPressed, child: child),
      DtxButtonKind.secondary => OutlinedButton(onPressed: onPressed, child: child),
      DtxButtonKind.link => TextButton(onPressed: onPressed, child: child),
    };
    return dtxStyled(context, style, Semantics(link: true, child: button));
  }
}
